# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DOĞADAKİ DÖRT TEMEL KUVVETİN ŞİDDET VE MENZİL KARŞILAŞTIRMASI</text>\n  <rect x="20" y="45" width="320" height="95" rx="8" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">1. GÜÇLÜ NÜKLEER (YEĞİN) KUVVET (En Güçlü: 1)</text>\n  <text x="32" y="88" font-size="10.5" fill="#7f1d1d">• Görevi: Atom çekirdeğindeki proton ve nötronları (ve kuarkları)</text>\n  <text x="40" y="103" font-size="10.5" fill="#7f1d1d">bir arada tutar, çekirdeğin dağılmasını önler.</text>\n  <text x="32" y="122" font-size="10.5" font-weight="bold" fill="#b91c1c">• Menzil: Çok kısa (~10^-15 m) · Taşıyıcı: Gluon</text>\n  <rect x="360" y="45" width="320" height="95" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">2. ELEKTROMANYETİK KUVVET (Bağıl Şiddet: ~10^-2)</text>\n  <text x="372" y="88" font-size="10.5" fill="#1e3a8a">• Görevi: Elektrik yüklü parçacıklar ve mıknatıslar arasındaki</text>\n  <text x="380" y="103" font-size="10.5" fill="#1e3a8a">itme-çekme kuvvetidir; atom ve molekülleri bir arada tutar.</text>\n  <text x="372" y="122" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Menzil: Sonsuz (1/r^2 ile azalır) · Taşıyıcı: Foton</text>\n  <rect x="20" y="152" width="320" height="92" rx="8" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="172" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">3. ZAYIF NÜKLEER KUVVET (Bağıl Şiddet: ~10^-13)</text>\n  <text x="32" y="192" font-size="10.5" fill="#78350f">• Görevi: Kararsız atom çekirdeklerinin radyoaktif bozunmasından</text>\n  <text x="40" y="207" font-size="10.5" fill="#78350f">(beta bozunması, nötron → proton dönüşümü) sorumludur.</text>\n  <text x="32" y="226" font-size="10.5" font-weight="bold" fill="#b45309">• Menzil: Çok kısa (~10^-18 m) · Taşıyıcı: W ve Z Bozonları</text>\n  <rect x="360" y="152" width="320" height="92" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="172" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">4. KÜTLE ÇEKİM KUVVETİ (En Zayıf: ~10^-38)</text>\n  <text x="372" y="192" font-size="10.5" fill="#14532d">• Görevi: Kütlesi/enerjisi olan tüm gök cisimlerini birbirine</text>\n  <text x="380" y="207" font-size="10.5" fill="#14532d">çeker (F = G·m1·m2/d^2); yalnız çekme özelliğindedir.</text>\n  <text x="372" y="226" font-size="10.5" font-weight="bold" fill="#166534">• Menzil: Sonsuz · Taşıyıcı: Graviton (varsayımsal)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TEMEL KUVVETLERİN BENZERLİK VE FARKLILIK MATRİSİ</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">TEMEL KUVVETLERİN ORTAK (BENZER) YÖNLERİ</text>\n  <text x="40" y="96" font-size="11" fill="#581c87">• Dördü de temas gerektirmeyen (alan) kuvvetlerdir.</text>\n  <text x="40" y="120" font-size="11" fill="#581c87">• Kuvvet vektöreldir, SI birimi Newton (N) olarak ölçülür.</text>\n  <text x="40" y="144" font-size="11" fill="#581c87">• Etkileşimler ayar bozonu (taşıyıcı parçacık) alışverişiyle olur.</text>\n  <text x="40" y="168" font-size="11" fill="#581c87">• Etki-tepki çifti hâlinde eşit büyüklük ve zıt yönde oluşur.</text>\n  <text x="40" y="192" font-size="11" fill="#581c87">• Evrendeki tüm diğer kuvvetler (sürtünme, ip gerilmesi, normal</text>\n  <text x="48" y="208" font-size="11" fill="#581c87">kuvvet, esneklik) bu dört temel kuvvete (özellikle EM\'ye) dayanır.</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#0e7490">AYIRT EDİCİ FARKLILIKLAR (SINIFLANDIRMA)</text>\n  <text x="375" y="96" font-size="11" font-weight="bold" fill="#155e75">• Şiddet Sıralaması (Büyükten Küçüğe — "GEZK"):</text>\n  <text x="383" y="114" font-size="10.5" fill="#0e7490">Güçlü Nükleer &gt; Elektromanyetik &gt; Zayıf Nükleer &gt; Kütle Çekim</text>\n  <text x="375" y="140" font-size="11" font-weight="bold" fill="#155e75">• Menzile Göre Gruplandırma:</text>\n  <text x="383" y="158" font-size="10.5" fill="#0e7490">- Sonsuz Menzilli: Elektromanyetik ve Kütle Çekim Kuvveti</text>\n  <text x="383" y="176" font-size="10.5" fill="#0e7490">- Kısa (Atom Altı) Menzilli: Güçlü Nükleer ve Zayıf Nükleer</text>\n  <text x="375" y="202" font-size="11" font-weight="bold" fill="#155e75">• İtme / Çekme Özelliği:</text>\n  <text x="383" y="220" font-size="10.5" fill="#0e7490">Kütle çekim kuvveti daima ÇEKME, EM kuvvet hem itme hem çekmedir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HAREKETİN TEMEL KAVRAMLARI: ALINAN YOL VE YER DEĞİŞTİRME</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">YÖRÜNGE ÜZERİNDE YOL VE YER DEĞİŞTİRME</text>\n  <circle cx="65" cy="175" r="7" fill="#dc2626"/>\n  <text x="65" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">A (İlk Konum)</text>\n  <circle cx="285" cy="115" r="7" fill="#16a34a"/>\n  <text x="285" y="98" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">B (Son Konum)</text>\n  <path d="M65,175 Q140,70 190,160 T285,115" fill="none" stroke="#2563eb" stroke-width="3" stroke-dasharray="6,4"/>\n  <line x1="65" y1="175" x2="285" y2="115" stroke="#dc2626" stroke-width="3"/>\n  <polygon points="285,115 271,113 275,124" fill="#dc2626"/>\n  <text x="155" y="95" font-size="11" font-weight="bold" fill="#1d4ed8">Alınan Yol (x) - Skaler</text>\n  <text x="195" y="168" font-size="11" font-weight="bold" fill="#b91c1c">Yer Değiştirme (Δx) - Vektörel</text>\n  <text x="35" y="224" font-size="10.5" fill="#1e3a8a">• Doğrusal ve yön değiştirmeyen harekette: x = |Δx|</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">SKALER VE VEKTÖREL HAREKET NİCELİKLERİ</text>\n  <text x="375" y="92" font-size="11" font-weight="bold" fill="#14532d">• Referans Noktası: Hareketin tanımlandığı başlangıç noktası</text>\n  <text x="375" y="114" font-size="11" font-weight="bold" fill="#14532d">• Konum (x): Referans noktasına olan yönlü uzaklık (Vektörel)</text>\n  <text x="375" y="136" font-size="11" font-weight="bold" fill="#14532d">• Alınan Yol (x): Gidilen yörüngenin toplam uzunluğu (Skaler)</text>\n  <text x="375" y="158" font-size="11" font-weight="bold" fill="#14532d">• Yer Değiştirme (Δx = x_son - x_ilk): En kısa yönlü uzaklık (Vektörel)</text>\n  <text x="375" y="182" font-size="11" font-weight="bold" fill="#1e40af">• Sürat (v = x / Δt): Birim zamanda alınan yol (Skaler, m/s)</text>\n  <text x="375" y="204" font-size="11" font-weight="bold" fill="#b91c1c">• Hız (v = Δx / Δt): Birim zamandaki yer değiştirme (Vektörel, m/s)</text>\n  <text x="375" y="226" font-size="10.5" fill="#166534">Not: Tam tur dönüp başladığı noktaya gelen cisimde Δx = 0, v = 0!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
